package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/comunicados")public class ComunicadoController{private final ComunicadoService s;public ComunicadoController(ComunicadoService s){this.s=s;}@GetMapping("/publicos")public List<ComunicadoResponse> publicos(){return s.publicos();}@GetMapping @PreAuthorize("hasRole('ADMINISTRADOR')")public List<ComunicadoResponse> listar(){return s.listar();}@GetMapping("/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public ComunicadoResponse buscar(@PathVariable Long id){return s.buscar(id);}@PostMapping @PreAuthorize("hasRole('ADMINISTRADOR')")public ResponseEntity<ComunicadoResponse> criar(@Valid @RequestBody ComunicadoRequest q){return ResponseEntity.status(201).body(s.criar(q));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public ComunicadoResponse editar(@PathVariable Long id,@Valid @RequestBody ComunicadoRequest q){return s.editar(id,q);}@PatchMapping("/{id}/arquivar")@PreAuthorize("hasRole('ADMINISTRADOR')")public ComunicadoResponse arquivar(@PathVariable Long id){return s.arquivar(id);}}
